import re
from typing import Tuple, Union, List

class Version:
    PRE_RELEASE_REGEX = re.compile(r"^[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*$")
    BUILD_REGEX = re.compile(r"^[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*$")
    FULL_VERSION_REGEX = re.compile(
        r"^(?P<major>0|[1-9]\d*)\."
        r"(?P<minor>0|[1-9]\d*)\."
        r"(?P<patch>0|[1-9]\d*)"
        r"(?:-(?P<prerelease>[0-9A-Za-z-.]+))?"
        r"(?:\+(?P<build>[0-9A-Za-z-.]+))?$"
    )

    @staticmethod
    def _parse_identifier(identifier: str) -> Union[int, str]:
        if identifier.isdigit():
            if len(identifier) > 1 and identifier.startswith('0'):
                raise ValueError(f"Numeric identifier '{identifier}' must not have leading zeros")
            return int(identifier)
        return identifier

    @staticmethod
    def parse(text: str) -> 'Version':
        match = Version.FULL_VERSION_REGEX.match(text)
        if not match:
            raise ValueError(f"Invalid version string: {text}")

        parts = match.groupdict()
        major = int(parts['major'])
        minor = int(parts['minor'])
        patch = int(parts['patch'])
        prerelease_str = parts.get('prerelease')
        build_str = parts.get('build')

        prerelease: Tuple[Union[int, str], ...] = tuple()
        if prerelease_str:
            identifiers = prerelease_str.split('.')
            for identifier in identifiers:
                if not identifier:
                    raise ValueError("Empty pre-release identifier")
                try:
                    prerelease.append(Version._parse_identifier(identifier))
                except ValueError as e:
                    raise ValueError(f"Invalid pre-release identifier '{identifier}': {e}")

        build: Tuple[str, ...] = tuple()
        if build_str:
            identifiers = build_str.split('.')
            for identifier in identifiers:
                if not identifier:
                    raise ValueError("Empty build identifier")
                # Build identifiers can have leading zeros, so they are strings
                build.append(identifier)

        return Version(major, minor, patch, prerelease, build)

    def __init__(self, major: int, minor: int, patch: int, prerelease: Tuple[Union[int, str], ...], build: Tuple[str, ...]):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    def __str__(self) -> str:
        # For canonical text, use the original parsed string if available, but since we don't store it,
        # we reconstruct it based on the parts.
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            prerelease_str = ".".join(
                str(item) if isinstance(item, int) else item for item in self.prerelease
            )
            s += f"-{prerelease_str}"
        if self.build:
            build_str = ".".join(self.build)
            s += f"+{build_str}"
        return s

    def __repr__(self) -> str:
        return f"Version('{self.major}.{self.minor}.{self.patch}{'-' + '.-'.join(map(str, self.prerelease) if self.prerelease else '')}{'+' + '.'.join(self.build) if self.build else ''}')"

    def __hash__(self) -> int:
        return hash((self.major, self.minor, self.patch, self.prerelease, self.build))

    def __eq__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        # Build metadata is ignored for equality
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch and
                self.prerelease == other.prerelease)

    def __lt__(self, other) -> bool:
        return self._compare(other) < 0

    def __le__(self, other) -> bool:
        return self._compare(other) <= 0

    def __gt__(self, other) -> bool:
        return self._compare(other) > 0

    def __ge__(self, other) -> bool:
        return self._compare(other) >= 0

    def _compare(self, other: 'Version') -> int:
        if not isinstance(other, Version):
            return NotImplemented

        # 1. Compare MAJOR, MINOR, PATCH numerically
        if self.major != other.major:
            return self.major - other.major
        if self.minor != other.minor:
            return self.minor - other.minor
        if self.patch != other.patch:
            return self.patch - other.patch

        # 2. Compare pre-release tags
        if self.prerelease and not other.prerelease:
            return -1  # Pre-release is lower than final
        if not self.prerelease and other.prerelease:
            return 1   # Final is higher than pre-release

        if self.prerelease and other.prerelease:
            len_self = len(self.prerelease)
            len_other = len(other.prerelease)
            for i in range(min(len_self, len_other)):
                id_self = self.prerelease[i]
                id_other = other.prerelease[i]

                if isinstance(id_self, int) and isinstance(id_other, int):
                    if id_self != id_other:
                        return int(id_self) - int(id_other)
                elif isinstance(id_self, int) and isinstance(id_other, str):
                    return -1 # Numeric < Alphanumeric
                elif isinstance(id_self, str) and isinstance(id_other, int):
                    return 1  # Alphanumeric > Numeric
                elif isinstance(id_self, str) and isinstance(id_other, str):
                    if id_self != id_other:
                        return 1 if id_self > id_other else -1

            # If all common identifiers are equal, the shorter list is lower
            if len_self != len_other:
                return len_self - len_other

