    major = int(parts['major'])
    minor = int(parts['minor']) if parts['minor'] else 0
    patch = int(parts['patch']) if parts['patch'] else 0

    # Ensure no pre-release or build parts are present in the string
    if '-' in version_str or '+' in version_str:
