        except Exception:
            raise ValueError(f"Malformed version in spec part: {part}")
    else:
        # Bare version or range operator prefix (^, ~)
        if part.startswith('^'):
            return ('^', part[1:])
        elif part.startswith('~'):
            return ('~', part[1:])
