            if not any(op in part for op in ['>=', '<=', '>', '<', '=', '^', '~']):
                op = '='
                version_str = part
            # Handling operators and anchors (^, ~)
            elif part.startswith('^'):
                op = '^'
                version_str = part[1:]
            elif part.startswith('~'):
                op = '~'
                version_str = part[1:]
