    """Checks a single comparator against the version."""
    comparison = v._compare(required)

    if op == '=':
        return comparison == 0
    elif op == '>':
        return comparison > 0
    elif op == '<':
        return comparison < 0
    elif op == '>=':
        return comparison >= 0
    elif op == '<=':
