        major_v, minor_v, patch_v = v.major, v.minor, v.patch
        major_r, minor_r, patch_r = required.major, required.minor, required.patch

        if major_r > 0:
            # ^1.2.3 is >=1.2.3 <2.0.0
            upper_bound = Version(major_r + 1, 0, 0, (), ())
            lower_bound = required
        else:
            # ^0.2.3 is >=0.2.3 <0.3.0
            if minor_r > 0:
                upper_bound = Version(0, minor_r + 1, 0, (), ())
                lower_bound = required
            else:
