                upper_bound = Version(0, 0, patch_r + 1, (), ())
                lower_bound = required

        return lower_bound <= v < upper_bound

    elif op == '~':
        # Tilde range logic
        major_v, minor_v, patch_v = v.major, v.minor, v.patch
        major_r, minor_r, patch_r = required.major, required.minor, required.patch

        if patch_r > 0:
