            upper_bound = Version(major_r, minor_r + 1, 0, (), ())
            lower_bound = required
        else:
            # ~1 is >=1.0.0 <2.0.0
            upper_bound = Version(major_r + 1, 0, 0, (), ())
            lower_bound = required

        return lower_bound <= v < upper_bound

    return False

