            raise ValueError("Leading 'v' is not allowed")

        match = re.match(r"^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$", text)
        if not match:
            raise ValueError(f"Invalid version string: {text}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))

        prerelease_str = match.group(4)
        build_str = match.group(5)

        prerelease = ()
        if prerelease_str:
            identifiers = prerelease_str.split('.')
            for identifier in identifiers:
                if not identifier:
                    raise ValueError("Empty pre-release identifier")
                prerelease = prerelease + (Version._parse_identifier(identifier),)

        build = ()
        if build_str:
            identifiers = build_str.split('.')
            for identifier in identifiers:
                if not identifier:
                    raise ValueError("Empty build identifier")
                build = build + (Version._parse_identifier(identifier),)

        return Version(major, minor, patch, prerelease, build)

