from datetime import date, timedelta
from typing import Iterable

def is_business_day(d: date, *, holidays: Iterable[date] = (), weekend: Iterable[int] = (5, 6)) -> bool:
    """
    Checks if a given date is a business day.
    """
    if d.weekday() in weekend:
        return False
    if d in set(holidays):
        return False
    return True

def business_days_between(start: date, end: date, *, include_start: bool = True, include_end: bool = False, holidays: Iterable[date] = (), weekend: Iterable[int] = (5, 6)) -> int:
    """
    Counts the number of business days between two dates.
    """
    if start > end:
        raise ValueError("start date must be less than or equal to end date")

    working_days = {i for i in range(7) if i not in weekend}
    if not working_days:
        raise ValueError("At least one weekday must remain a working day.")

    count = 0
    current_date = start

    if include_start:
        if is_business_day(start, holidays=holidays, weekend=weekend):
            count += 1

    while current_date < end:
        current_date += timedelta(days=1)
        if current_date > end:
            break

        if is_business_day(current_date, holidays=holidays, weekend=weekend):
            count += 1

    if include_end and start <= end:
        if is_business_day(end, holidays=holidays, weekend=weekend):
            # Avoid double counting if start == end and include_start=True
            if not (start == end and include_start):
                count += 1

    # Special case for start == end
    if start == end:
        if include_start and is_business_day(start, holidays=holidays, weekend=weekend) and not include_end:
            return 1
        if include_end and is_business_day(start, holidays=holidays, weekend=weekend) and not include_start:
            return 1
        if include_start and include_end and is_business_day(start, holidays=holidays, weekend=weekend):
            return 1
        return 0

    return count

def add_business_days(d: date, n: int, *, holidays: Iterable[date] = (), weekend: Iterable[int] = (5, 6)) -> date:
    """
    Adds or subtracts a specified number of business days from a date.
    """
    if n > 0:
        current_date = d + timedelta(days=1)
        count = 0
        while count < n:
            if is_business_day(current_date, holidays=holidays, weekend=weekend):
                count += 1
            current_date += timedelta(days=1)
        return current_date
    elif n < 0:
        current_date = d - timedelta(days=1)
        count = 0
        while count < abs(n):
            if is_business_day(current_date, holidays=holidays, weekend=weekend):
                count += 1
            current_date -= timedelta(days=1)
        return current_date
    else: # n == 0
        if is_business_day(d, holidays=holidays, weekend=weekend):
            return d
        current_date = d + timedelta(days=1)
        while not is_business_day(current_date, holidays=holidays, weekend=weekend):
            current_date += timedelta(days=1)
