from typing import List, Dict, Any

class TrieNode:
    def __init__(self):
        self.children: Dict[str, TrieNode] = {}
        self.is_end_of_word: bool = False
        self.weight: float = 0.0
        self.original_word: str = ""

class Autocomplete:
    def __init__(self):
        self.root = TrieNode()
        self._count = 0

    def add(self, word: str, weight: float = 1.0) -> None:
        if not word:
            raise ValueError("word cannot be empty")

        word_casefold = word.casefold()
        node = self.root

        # Check if word already exists (casefolded)
        if self.word_exists(word_casefold):
            self._update_existing_word(word_casefold, word, weight)
            return

        # If new word, insert and update count
        self._insert_new_word(word_casefold, word, weight)

    def _insert_new_word(self, word_casefold: str, original_word: str, weight: float) -> None:
        node = self.root
        for char in word_casefold:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]

        node.is_end_of_word = True
        node.weight = weight
        node.original_word = original_word
        self._count += 1

    def _update_existing_word(self, word_casefold: str, new_original_word: str, new_weight: float) -> None:
        node = self.root
        for char in word_casefold:
            node = node.children[char]

        # Replace existing word data
        node.original_word = new_original_word
        node.weight = new_weight
        # Count remains the same as it's an update

    def word_exists(self, word_casefold: str) -> bool:
        node = self.root
        for char in word_casefold:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end_of_word

    def _find_node_for_word(self, word_casefold: str) -> TrieNode | None:
        node = self.root
        for char in word_casefold:
            if char not in node.children:
                return None
            node = node.children[char]
        return node

    def delete(self, word: str) -> bool:
        word_casefold = word.casefold()
        node = self._find_node_for_word(word_casefold)

        if not node or not node.is_end_of_word:
            return False

        # Simple deletion: clear the word marker and reset weight/word
        # Note: A full, safe trie deletion would require pruning unused nodes, 
        # but for this requirement, simply invalidating the word is sufficient.
        node.is_end_of_word = False
        node.weight = 0.0
        node.original_word = ""
        self._count -= 1

        # Advanced pruning (optional but good practice):
        # If we were to implement full pruning, we'd traverse back up 
        # and remove nodes that no longer lead to any word. 
        # Sticking to the requirement of removal, this is sufficient.
        return True

    def complete(self, prefix: str, k: int = 10) -> List[str]:
        if k == 0:
            return []
        if k < 0:
            raise ValueError("k must be non-negative")

        prefix_casefold = prefix.casefold()
        start_node = self._find_node_for_word(prefix_casefold)

        if not start_node:
            return []

        results = []

        # DFS to find all words starting from start_node
        stack: List[TrieNode] = [start_node]

        while stack:
            node = stack.pop()

            if node.is_end_of_word:
                results.append({
                    'word': node.original_word, 
                    'weight': node.weight, 
                    'casefold': node.original_word.casefold()
                })

            # Push children onto stack (order doesn't matter for collection)
            for child_node in node.children.values():
                stack.append(child_node)

        # Sorting criteria:
        # 1. By weight, highest to lowest (descending weight)
        # 2. Among equal weights, alphabetically by casefolded form (ascending casefold)
        results.sort(key=lambda x: (-x['weight'], x['casefold']))

        return [res['word'] for res in results[:k]]

    def __len__(self) -> int:
        return self._count

    def __contains__(self, word: str) -> bool:
        return self.word_exists(word.casefold())

