def first_index(a: list[int], x: int) -> int:
    """Returns the index of the first element equal to x, or -1 if there is none."""
    low, high = 0, len(a) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == x:
            result = mid
            high = mid - 1
        elif a[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return result

def last_index(a: list[int], x: int) -> int:
    """Returns the index of the last element equal to x, or -1 if there is none."""
    low, high = 0, len(a) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == x:
            result = mid
            low = mid + 1
        elif a[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return result

def insertion_point(a: list[int], x: int) -> int:
    """
    Returns the smallest index i such that inserting x before a[i] keeps a sorted.
    Returns len(a) if x is greater than every element.
    """
    low, high = 0, len(a)
    while low < high:
        mid = (low + high) // 2
        if a[mid] < x:
            low = mid + 1
        else:
            high = mid
    return low

def count(a: list[int], x: int) -> int:
    """Returns how many elements equal x."""
    first = first_index(a, x)
    if first == -1:
        return 0
    last = last_index(a, x)
    return last - first + 1

def search_rotated(a: list[int], x: int) -> int:
    """
    Searches for x in a rotated sorted list of distinct values.
    Returns the index of x, or -1.
    """
    if not a:
        return -1

    low, high = 0, len(a) - 1

    while low <= high:
        mid = (low + high) // 2

        if a[mid] == x:
            return mid

        # Check which side is normally sorted
        if a[low] <= a[mid]:  # Left side is sorted
            if a[low] <= x < a[mid]:
                # x is in the sorted left half
                high = mid - 1
            else:
                # x is in the rotated right half
                low = mid + 1
        else:  # Right side is sorted (a[mid] < a[high])
            if a[mid] < x <= a[high]:
                # x is in the sorted right half
                low = mid + 1
            else:
                # x is in the rotated left half
                high = mid - 1

    return -1

def rotation_offset(a: list[int]) -> int:
    """
    For a rotated list, returns the index of its smallest element (0 for unrotated).
    Raises ValueError if a is empty.
    """
    if not a:
        raise ValueError("rotation_offset requires a non-empty list")

    low, high = 0, len(a) - 1

    # If the list is not rotated
    if a[low] <= a[high]:
        return 0

    while low <= high:
        mid = (low + high) // 2

        # Check if mid is the minimum element
        if mid > 0 and a[mid] < a[mid - 1]:
            return mid

        # Decide which half to search
        if a[mid] > a[high]:
            # The minimum is in the right half
            low = mid + 1
        else:
            # The minimum is in the left half (or is mid itself, handled above)
            high = mid - 1

    # Should not be reached for a valid rotated array, but for safety:
    return 0

def isqrt(n: int) -> int:
    """
    Returns the largest integer r with r * r <= n, exact for arbitrarily large integers.
    Raises ValueError if n is negative; TypeError if n is not an int (a bool counts as not an int).
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    if n == 0:
        return 0

    # Binary search approach for integer square root
    low = 1
    high = n

    result = 1
    while low <= high:
        mid = (low + high) // 2

        mid_sq = mid * mid

        if mid_sq <= n:
            result = mid
            low = mid + 1  # Try for a larger root
        else:
            high = mid - 1 # mid is too large

    return result
