class EmitError(Exception):
    def __init__(self, errors):
        self.errors = errors
        super().__init__(f"One or more listeners raised exceptions: {[err[1] for err in errors]}")

class Emitter:
    def __init__(self):
        self._listeners = {}

    def on(self, event, listener):
        if event not in self._listeners:
            self._listeners[event] = []
        self._listeners[event].append(listener)
        return listener

    def once(self, event, listener):
        if event not in self._listeners:
            self._listeners[event] = []
        self._listeners[event].append(listener)

        # Wrap the listener to remove itself after one call
        def wrapper(*args, **kwargs):
            self.off(event, wrapper)
            listener(*args, **kwargs)

        self._listeners[event][-1] = wrapper
        return wrapper

    def off(self, event, listener=None) -> int:
        if event not in self._listeners:
            return 0

        registrations = self._listeners[event]

        if listener is None:
            count = len(registrations)
            self._listeners[event] = []
            return count
        else:
            count = 0
            # Iterate backward to safely remove elements
            i = len(registrations) - 1
            while i >= 0:
                reg = registrations[i]
                # Check if the registration matches the listener exactly
                if reg is listener:
                    registrations.pop(i)
                    count += 1
                    # If the listener was a wrapper created by once, we need to ensure 
                    # the original logic holds, but for simplicity in off, we remove the wrapper.
                    # If the original listener was passed to off, it must match the reference.
                i -= 1
            return count

    def emit(self, event, *args, **kwargs) -> int:
        if event not in self._listeners:
            return 0

        # Get a fixed list of current listeners to iterate over
        listeners_to_call = list(self._listeners[event])
        calls_made = 0
        errors_encountered = []

        for listener in listeners_to_call:
            try:
                listener(*args, **kwargs)
                calls_made += 1
            except Exception as e:
                calls_made += 1
                errors_encountered.append((listener, e))

        if errors_encountered:
            raise EmitError(errors_encountered)

        return calls_made

    def listeners(self, event) -> list:
        if event not in self._listeners:
            return []
        # Return a copy to prevent external modification of internal state
        return list(self._listeners[event])
