# fsm/machine.py
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple, Union

class MachineError(Exception):
    pass

@dataclass
class InvalidTransition(MachineError):
    state: str
    event: str

@dataclass
class GuardRejected(MachineError):
    state: str
    event: str

@dataclass
class State:
    name: str
    on_enter: Optional[callable] = None
    on_exit: Optional[callable] = None

@dataclass
class Transition:
    event: str
    source: Union[str, List[str], Tuple[str, ...]]
    target: Optional[str]
    guard: Optional[callable] = None
    action: Optional[callable] = None

@dataclass
class Event:
    name: str
    source: str
    target: str
    data: Dict[str, Any] = field(default_factory=dict)

class Machine:
    def __init__(self, states: List[Union[str, State]], transitions: List[Transition], initial: str, context: Optional[Any] = None):
        if not states:
            raise ValueError("States list cannot be empty.")

        state_map: Dict[str, State] = {}
        state_names: set[str] = set()

        for state_item in states:
            if isinstance(state_item, str):
                name = state_item
                state_names.add(name)
                state_map[name] = State(name=name)
            elif isinstance(state_item, State):
                name = state_item.name
                state_names.add(name)
                state_map[name] = state_item
            else:
                raise TypeError("States must be strings or State objects.")

        if len(state_map) != len(state_names):
            # Should not happen if logic above is correct, but as a safeguard
            raise ValueError("Two states share a name.")

        if initial not in state_names:
            raise ValueError(f"Initial state '{initial}' is not a defined state.")

        self.states_data: Dict[str, State] = state_map
        self.transitions: List[Transition] = transitions
        self.initial = initial
        self.context: Optional[Any] = context
        self.state: str = initial
        self.history: List[Tuple[str, str, str]] = []
        self._listeners: List[callable] = []

        self._validate_transitions()

    def _validate_transitions(self):
        valid_states = set(self.states_data.keys())
        for t in self.transitions:
            source_list = t.source
            if isinstance(source_list, str):
                if source_list != '*' and source_list not in valid_states:
                    raise ValueError(f"Transition source '{source_list}' is not a valid state.")
            elif isinstance(source_list, (list, tuple)):
                for src in source_list:
                    if src != '*' and src not in valid_states:
                        raise ValueError(f"Transition source '{src}' is not a valid state.")
            elif source_list is None:
                raise ValueError("Transition source cannot be None.")

            target_val = t.target
            if target_val is not None and target_val not in valid_states:
                raise ValueError(f"Transition target '{target_val}' is not a valid state.")

    def can_fire(self, event: str, **data) -> bool:
        candidates = [
            t for t in self.transitions
            if t.event == event and (
                t.source == '*' or (isinstance(t.source, str) and t.source == self.state) or (isinstance(t.source, (list, tuple)) and self.state in t.source)
            )
        ]

        for t in candidates:
            if t.guard is None:
                return True
            try:
                if t.guard(self, Event(t.event, self.state, t.target if t.target else self.state, data)):
                    return True
            except Exception:
                # Guard exception, treat as failure to transition
                pass
        return False

    def available_events(self) -> List[str]:
        events = set()
        for t in self.transitions:
            if t.event and (
                t.source == '*' or (isinstance(t.source, str) and t.source == self.state) or (isinstance(t.source, (list, tuple)) and self.state in t.source)
            ):
                events.add(t.event)
        return sorted(list(events))

    def on_transition(self, listener: callable):
        self._listeners.append(listener)

    def reset(self):
        self.state = self.initial
        self.history = []

    def fire(self, event: str, **data) -> str:
        if hasattr(self, '_firing'):
            raise MachineError("Cannot fire while another fire call is running.")

        self._firing = True
        try:
            candidates = [
                t for t in self.transitions
                if t.event == event and (
                    t.source == '*' or (isinstance(t.source, str) and t.source == self.state) or (isinstance(t.source, (list, tuple)) and self.state in t.source)
                )
            ]

            if not candidates:
                raise InvalidTransition(state=self.state, event=event)

            event_data = Event(name=event, source=self.state, target=self.state, data=data)

            # 3. Evaluate guards
            chosen_transition: Optional[Transition] = None
            for t in candidates:
                if t.guard is None:
                    chosen_transition = t
                    break
                try:
                    if t.guard(self, event_data):
                        chosen_transition = t
                        break
                except Exception:
                    # Guard failed due to exception
                    pass

            if chosen_transition is None:
                raise GuardRejected(state=self.state, event=event)

            t = chosen_transition

            # State change tracking for rollback if exception occurs
            old_state = self.state
            target_state = t.target if t.target is not None else self.state

            # 4. Normal transition logic
            if t.target is not None:
                # Normal transition
                try:
                    # on_exit
                    if self.states_data[self.state].on_exit:
                        self.states_data[self.state].on_exit(self, event_data)

                    # transition action
                    if t.action:
                        t.action(self, event_data)

                    # Set state and record history
                    self.state = target_state
                    self.history.append((old_state, event, target_state))

                    # on_enter
                    if self.states_data[self.state].on_enter:
                        self.states_data[self.state].on_enter(self, event_data)

                    # listeners
                    for listener in self._listeners:
                        listener(old_state, event_data, target_state)

                except Exception as e:
                    # Exception from on_exit, action, on_enter, or listener.
                    # Rollback if it came before state change, otherwise let it propagate.
                    if t.target is not None and self.state != target_state:
                        # State changed, so we let the exception propagate.
                        raise e
                    # If exception occurred before state change, revert state and history
                    self.state = old_state
                    self.history.pop()
                    raise e
            else:
                # 5. Internal transition
                try:
                    # action
                    if t.action:
                        t.action(self, event_data)

                    # Record history (target is source for internal)
                    self.history.append((old_state, event, old_state))

                    # listeners
                    for listener in self._listeners:
                        listener(old_state, event_data, old_state)

                except Exception as e:
                    # Internal transitions don't change state, so no rollback needed for state/history
                    raise e

            return self.state

        finally:
            self._firing = False

