import math
from typing import Dict, Tuple, List, Optional

# Import from fsm package
from fsm.machine import (
    Machine,
    State,
    Transition,
    Event,
    MachineError,
    InvalidTransition,
    GuardRejected,
)

# --- Vending Specific Exceptions ---
class VendingError(Exception):
    pass

class SoldOut(VendingError):
    pass

class InsufficientCredit(VendingError):
    pass

# --- Coin Values for Change ---
CHANGE_COINS = [100, 25, 10, 5]

class VendingMachine:
    def __init__(self, products: Dict[str, Tuple[int, int]]):
        self.products: Dict[str, Tuple[int, int]] = products  # code: (price, stock)
        self.product_prices: Dict[str, int] = {code: price for code, (price, _) in products.items()}
        self.product_stocks: Dict[str, int] = {code: stock for code, (_, stock) in products.items()}

        # Initial setup for FSM states
        initial_state = 'idle'

        # Define states
        states = [
            State(name='idle'),
            State(name='credit'),
            State(name='maintenance')
        ]

        # Define transitions
        transitions = []

        # --- Transitions from Idle ---
        # Idle -> Credit (Insert Coin)
        transitions.append(Transition(
            event='insert', 
            source='idle', 
            target='credit', 
            action=self._transition_insert_idle
        ))
        # Idle -> Maintenance (Service)
        transitions.append(Transition(
            event='service', 
            source='idle', 
            target='maintenance'
        ))

        # --- Transitions from Credit ---
        # Credit -> Idle (Select Product)
        # Note: Selection logic is handled by the action/guards in fire, 
        # but we define the state change here.
        transitions.append(Transition(
            event='select', 
            source='credit', 
            target='idle', 
            action=self._transition_select_credit
        ))
        # Credit -> Idle (Cancel)
        transitions.append(Transition(
            event='cancel', 
            source='credit', 
            target='idle', 
            action=self._transition_cancel_credit
        ))
        # Credit -> Credit (Internal transition for inserting more coin)
        transitions.append(Transition(
            event='insert', 
            source='credit', 
            target=None, 
            action=self._transition_insert_credit
        ))

        # --- Transitions from Maintenance ---
        # Maintenance -> Idle (Resume)
        transitions.append(Transition(
            event='resume', 
            source='maintenance', 
            target='idle'
        ))
        # Maintenance -> Maintenance (Restock - Internal transition)
        transitions.append(Transition(
            event='restock', 
            source='maintenance', 
            target=None, 
            action=self._transition_restock_maintenance
        ))

        # Initialize Machine
        self.machine = Machine(states, transitions, initial_state, context=self)

        # Machine state tracking
        self._credit: int = 0
        self._sales: Dict[str, int] = {}
        self._revenue: int = 0

        # Register listeners for state changes if needed, though the machine handles basic flow
        self.machine.on_transition(self._on_transition_listener)

    # --- Internal Helper Methods ---

    def _get_change(self, amount: int) -> List[int]:
        """Greedily calculates change coins."""
        change = []
        remaining = amount
        for coin in CHANGE_COINS:
            count = remaining // coin
            change.extend([coin] * count)
            remaining %= coin
        return change

    def _on_transition_listener(self, source: str, event_data: Event, target: str):
        # This listener runs after state/history updates
        if event_data.name == 'insert':
            if target == 'credit' and source == 'idle':
                # This handles the initial credit state change from idle
                pass 
            elif target == 'credit' and source == 'credit':
                # This handles internal credit update
                pass

        # In a real scenario, we might update derived properties here if necessary
        pass


    # --- State Transition Actions (Hooks) ---

    def _transition_insert_idle(self, machine: Machine, event: Event):
        coin = event.data.get('coin')
        if coin is None:
            # Should not happen if called correctly, but defensive
            raise ValueError("Coin must be provided in event data for 'insert' from 'idle'.")
        if coin not in [5, 10, 25, 100]:
            raise ValueError("Coin not accepted.")

        self._credit += coin
        # The state change (idle -> credit) is handled by the Machine itself
        # The credit update is reflected in self._credit

    def _transition_insert_credit(self, machine: Machine, event: Event):
        coin = event.data.get('coin')
        if coin is None:
            raise ValueError("Coin must be provided in event data for internal 'insert'.")
        if coin not in [5, 10, 25, 100]:
            raise ValueError("Coin not accepted.")

        self._credit += coin
        # The state remains 'credit', so we just update context/state

    def _transition_select_credit(self, machine: Machine, event: Event):
        code = event.data.get('code')
        if code is None:
            raise ValueError("Product code must be provided for 'select'.")

        price = self.product_prices[code]

        if self.product_stocks[code] <= 0:
            raise SoldOut()

        if self._credit < price:
            raise InsufficientCredit()

        # Successful sale logic
        self.product_stocks[code] -= 1
        change_amount = self._credit - price
        self._credit = 0
        self._sales[code] = self._sales.get(code, 0) + 1
        self._revenue += price

        # The state change (credit -> idle) is handled by the Machine itself
        # We return the change coins in the event data for the caller to use, though 
        # the Machine structure doesn't explicitly pass return values from actions easily.
        # For this design, we assume the calling method (select) handles the return value.
        # Since we can't easily return values from hooks to the fire method, 
        # we must rely on the caller knowing the machine context.
        event.data['change'] = self._get_change(change_amount)

    def _transition_cancel_credit(self, machine: Machine, event: Event):
        # Refund all credit
        refund_coins = self._get_change(self._credit)
        self._credit = 0
        event.data['refund'] = refund_coins

    def _transition_restock_maintenance(self, machine: Machine, event: Event):
        code = event.data.get('code')
        qty = event.data.get('qty')
        price = event.data.get('price')

        if qty is None or qty < 1:
            raise ValueError("Quantity must be provided and be >= 1.")

        if code not in self.products:
            if price is None:
                raise KeyError(f"Price must be provided for new product code: {code}")
            self.products[code] = (price, 0)
            self.product_prices[code] = price
            self.product_stocks[code] = 0
        else:
            if price is not None:
                self.products[code] = (price, self.product_stocks[code]) # Stock is kept, price is updated
                self.product_prices[code] = price

        # Add stock
        self.product_stocks[code] = self.product_stocks.get(code, 0) + qty

        # State remains 'maintenance'

    # --- Public API Methods ---

    @property
    def state(self) -> str:
        return self.machine.state

    @property
    def credit(self) -> int:
        return self._credit

    def stock(self, code: str) -> int:
        if code not in self.product_stocks:
            raise KeyError(f"Product code '{code}' not found.")
        return self.product_stocks[code]

    def price(self, code: str) -> int:
        if code not in self.product_prices:
            raise KeyError(f"Product code '{code}' not found.")
        return self.product_prices[code]

    @property
    def sales(self) -> Dict[str, int]:
        return self._sales

    @property
    def revenue(self) -> int:
        return self._revenue

    def insert(self, coin: int) -> int:
        if self.state not in ['idle', 'credit']:
            raise InvalidTransition(state=self.state, event='insert')

        event_data = {'coin': coin}

        try:
            self.machine.fire('insert', **event_data)
            return self._credit
        except (MachineError, ValueError) as e:
            # MachineError/ValueError from hook/transition action means no change occurred
            raise e

    def select(self, code: str) -> List[int]:
        if self.state != 'credit':
            raise InvalidTransition(state=self.state, event='select')

        event_data = {'code': code}

        try:
            new_state = self.machine.fire('select', **event_data)
            if new_state == 'idle':
                # Extract change from the event data set during the transition
                return event_data.get('change', [])
            else:
                # Should not happen if transition is correct
                return []
        except (MachineError, KeyError, SoldOut, InsufficientCredit) as e:
            # A failed select leaves state, credit, and stock unchanged.
            # Re-raise the specific vending error or transition error.
            raise e
        except Exception:
            # Catch any other unforeseen errors during fire and leave state unchanged
            pass

    def cancel(self) -> List[int]:
        if self.state != 'credit':
            raise InvalidTransition(state=self.state, event='cancel')

        event_data = {}
        try:
            self.machine.fire('cancel', **event_data)
            return event_data.get('refund', [])
        except MachineError as e:
            raise e

    def service(self) -> None:
        if self.state != 'idle':
            raise InvalidTransition(state=self.state, event='service')

        try:
            self.machine.fire('service')
        except MachineError as e:
            raise e

    def restock(self, code: str, qty: int, price: Optional[int] = None) -> None:
        if self.state != 'maintenance':
            raise InvalidTransition(state=self.state, event='restock')

        event_data = {'code': code, 'qty': qty, 'price': price}

        try:
            self.machine.fire('restock', **event_data)
        except MachineError as e:
            raise e

    def resume(self) -> None:
        if self.state != 'maintenance':
            raise InvalidTransition(state=self.state, event='resume')

        try:
            self.machine.fire('resume')
        except MachineError as e:
