from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Union, Tuple

# --- Exceptions ---
class MachineError(Exception):
    pass

class InvalidTransition(MachineError):
    def __init__(self, state: str, event: str):
        super().__init__(f"Invalid transition from state '{state}' on event '{event}'")
        self.state = state
        self.event = event

class GuardRejected(MachineError):
    def __init__(self, state: str, event: str):
        super().__init__(f"All transitions for event '{event}' from state '{state}' were rejected by guards")
        self.state = state
        self.event = event

# --- Data Classes ---
@dataclass
class State:
    name: str
    on_enter: Optional[callable] = None
    on_exit: Optional[callable] = None

@dataclass
class Transition:
    event: str
    source: Union[str, List[str], Tuple[str, ...]]
    target: Optional[Union[str, None]]
    guard: Optional[callable] = None
    action: Optional[callable] = None

@dataclass
class Event:
    name: str
    source: str
    target: str
    data: Dict[str, Any] = field(default_factory=dict)

# --- Machine ---
class Machine:
    def __init__(self, states: List[Union[str, State]], transitions: List[Transition], initial: str, context: Optional[Any] = None):
        self._states_map: Dict[str, Any] = {}
        self._transitions: List[Transition] = transitions
        self._listeners: List[callable] = []
        self._initial_state_name = initial
        self.context = context
        self.history: List[Tuple[str, str, str]] = []

        # Process states
        state_names = set()
        for state_def in states:
            name = state_def.name if isinstance(state_def, State) else state_def
            if name in state_names:
                raise ValueError(f"Duplicate state name found: {name}")
            self._states_map[name] = state_def if isinstance(state_def, State) else None
            state_names.add(name)

        if initial not in state_names:
            raise ValueError(f"Initial state '{initial}' is not defined.")

        self.state: str = initial
        self.history = []

        # Pre-check transitions for valid sources/targets (simplified for constructor logic, full check happens implicitly during fire)
        # A full check would iterate transitions here, but we rely on fire to validate.
        pass

    def _check_state_existence(self, state_name: str):
        if state_name not in self._states_map:
            raise ValueError(f"Transition references unknown state: {state_name}")

    def can_fire(self, event: str, **data) -> bool:
        candidates = [t for t in self._transitions if t.event == event and self._source_matches(t.source)]

        if not candidates:
            return False

        for candidate in candidates:
            if candidate.guard is None:
                return True
            try:
                if candidate.guard(self, Event(candidate.event, self.state, candidate.target if candidate.target else self.state, data)):
                    return True
            except Exception:
                # Guard raised an exception, treat as rejection for safety in can_fire
                continue

        return False

    def available_events(self) -> List[str]:
        events = set()
        for t in self._transitions:
            if t.source == '*' or self._source_matches(t.source):
                events.add(t.event)
        return sorted(list(events))

    def _source_matches(self, source: Union[str, List[str], Tuple[str, ...]]) -> bool:
        if source == '*':
            return True
        if isinstance(source, str):
            return source == self.state
        if isinstance(source, (list, tuple)):
            return self.state in source
        return False

    def on_transition(self, listener: callable):
        self._listeners.append(listener)

    def reset(self):
        self.state = self._initial_state_name
        self.history = []

    def fire(self, event: str, **data) -> str:
        if hasattr(self, '_running_fire'):
            raise MachineError("Cannot fire while another fire call is in progress.")

        self._running_fire = True

        candidates = [t for t in self._transitions if t.event == event and self._source_matches(t.source)]

        if not candidates:
            self._running_fire = False
            raise InvalidTransition(self.state, event)

        event_data = Event(event, self.state, "", data)

        chosen_transition: Optional[Transition] = None

        # 3. Guard evaluation
        for candidate in candidates:
            if candidate.guard is None:
                chosen_transition = candidate
                break
            try:
                if candidate.guard(self, event_data):
                    chosen_transition = candidate
                    break
            except Exception:
                # Guard raised exception, move to next candidate
                continue

        if chosen_transition is None:
            self._running_fire = False
            raise GuardRejected(self.state, event)

        # 4 & 5. Transition execution
        transition = chosen_transition
        old_state = self.state
        new_state = transition.target if transition.target is not None else old_state

        transition_succeeded = True

        try:
            # 4. Normal transition logic
            if transition.target is not None:
                # Normal transition
                if transition.action:
                    transition.action(self, event_data)

                # Set state and record history
                self.state = new_state
                self.history.append((old_state, event, new_state))

                if transition.target is not None: # Should always be true here, but for clarity
                    if transition.target != old_state:
                        if transition.target_state_def := self._states_map[new_state]:
                            if transition_succeeded:
                                if transition_succeeded and transition.target_state_def and transition.target_state_def.on_enter:
                                    transition.target_state_def.on_enter(self, event_data)

                        # 4. Call listeners
                        for listener in self._listeners:
                            listener(old_state, event_data, new_state)
                    else: # Internal transition (target == source)
                        if transition_succeeded and transition.target_state_def and transition.target_state_def.on_enter:
                            transition.target_state_def.on_enter(self, event_data)

                        # 4. Call listeners (for internal too)
                        for listener in self._listeners:
                            listener(old_state, event_data, new_state)

            # 5. Internal transition logic (target=None)
            elif transition.target is None:
                # Internal transition runs only action, records history, and calls listeners
                if transition.action:
                    transition.action(self, event_data)

                self.history.append((old_state, event, old_state))

                for listener in self._listeners:
                    listener(old_state, event_data, old_state)

        except Exception as e:
            # 6. Exception handling
            if isinstance(e, MachineError):
                # Guard or action raised MachineError, state/history unchanged
                pass
            elif transition_succeeded and self.state != old_state:
                # Exception from on_enter or listener (state already changed)
                raise e
            else:
                # Exception from guard or action, state/history unchanged
                pass
        finally:
            self._running_fire = False

        return self.state
