from .versions import Version, Range

class PackageIndex:
    def __init__(self):
        self._packages = {}  # {name: {version_str: {'requires': {dep_name: Range, ...}}}}

    def add(self, name: str, version_str: str, requires: dict = None):
        if name in self._packages and version_str in self._packages[name]:
            raise ValueError(f"Version {version_str} already exists for package {name}.")

        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Bad version string '{version_str}': {e}")

        if name not in self._packages:
            self._packages[name] = {}

        self._packages[name][version_str] = {'requires': {}}

        if requires:
            for dep_name, spec_str in requires.items():
                try:
                    range_obj = Range(spec_str)
                    self._packages[name][version_str]['requires'][dep_name] = range_obj
                except ValueError as e:
                    raise ValueError(f"Bad requirement spec for {name}@{version_str} on {dep_name}: {e}")

    def versions(self, name: str) -> list[Version]:
        if name not in self._packages:
            return []

        versions = [Version(v) for v in self._packages[name]]
        # Return newest first
        return sorted(versions, reverse=True)

    def requirements(self, name: str, version_str: str) -> dict[str, Range]:
        if name not in self._packages or version_str not in self._packages[name]:
            raise KeyError(f"Version {version_str} of package {name} not found.")

        return self._packages[name][version_str]['requires']

    @classmethod
    def from_dict(cls, data: dict) -> 'PackageIndex':
        index = cls()
        for name, versions_data in data.items():
            index._packages[name] = {}
            for version_str, dep_map in versions_data.items():
                index.add(name, version_str, requires=dep_map)
        return index
