from .index import PackageIndex
from .versions import Version, Range
import collections
from typing import Dict, List, Tuple, Optional

class ResolutionError(Exception):
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation
        super().__init__(explanation)

def resolve(index: PackageIndex, requirements: Dict[str, str]) -> Dict[str, Version]:

    # 1. Initial setup
    order = sorted(requirements.keys())

    # State tracking for the search
    selected_packages: Dict[str, Version] = {}  # {name: selected_version}

    # DFS helper function
    def dfs(current_order: List[str], current_selection: Dict[str, Version]) -> Optional[Dict[str, Version]]:

        if not current_order:
            return current_selection

        package_name = current_order[0]
        remaining_order = current_order[1:]

        # 2. Determine constraints for package_name
        constraints: List[Tuple[str, Range, str]] = [] # (requirer, range, version_str_of_requirer)

        # Root requirement constraint
        root_spec = requirements.get(package_name)
        if root_spec:
            try:
                root_range = Range(root_spec)
                constraints.append(("<root>", root_range, "<root>"))
            except ValueError as e:
                # Should be caught before DFS, but as a safeguard
                raise ResolutionError(package_name, f"Root requirement failed validation: {e}")

        # Constraints from already selected packages
        for selected_name, selected_version in current_selection.items():
            try:
                reqs = index.requirements(selected_name, str(selected_version))
                if package_name in reqs:
                    req_range = reqs[package_name]
                    requirer_id = f"{selected_name} {str(selected_version)}"
                    constraints.append((requirer_id, req_range, requirer_id))
            except KeyError:
                # Should not happen if logic is correct, but if selection is inconsistent
                continue

        # 3. Get candidates (newest first)
        candidates = index.versions(package_name)

        for candidate_version in candidates:
            candidate_str = str(candidate_version)
            is_acceptable = True

            # Check 1: Acceptability against constraints
            for requirer, req_range, requirer_id in constraints:
                if not req_range.contains(candidate_version):
                    is_acceptable = False
                    break

            if not is_acceptable:
                continue

            # Check 2: Acceptability against already selected dependencies (internal check)
            is_fully_acceptable = True

            # Get dependencies required by this candidate version
            try:
                candidate_reqs = index.requirements(package_name, candidate_str)
            except KeyError:
                # Should not happen if candidate came from index.versions
                continue

            for dep_name, dep_range in candidate_reqs.items():
                if dep_name in current_selection:
                    selected_dep_version = current_selection[dep_name]
                    if not dep_range.contains(selected_dep_version):
                        is_fully_acceptable = False
                        break

            if not is_fully_acceptable:
                continue

            # Candidate is acceptable. Proceed recursively.

            # Determine new order additions
            newly_added_deps = []
            for dep_name in candidate_reqs.keys():
                if dep_name not in current_order and dep_name not in current_selection:
                    newly_added_deps.append(dep_name)

            # Append new dependencies in alphabetical order to the order list
            new_order = current_order + sorted(newly_added_deps)

            # Update selection state
            new_selection = current_selection.copy()
            new_selection[package_name] = candidate_version

            # Recurse
            result = dfs(new_order, new_selection)

            if result is not None:
                return result

        # 4. Failure case: No acceptable candidate found for package_name

        error_lines = []

        # 1. Cannot resolve NAME
        error_lines.append(f"cannot resolve {package_name}")

        # 2. Constraints
        for requirer, req_range, requirer_id in constraints:
            error_lines.append(f"  {requirer_id} requires {package_name} {str(req_range)}")

        # 3. Version exclusion reasons (if versions exist)
        if index.versions(package_name):
            # Check each version against constraints again to find the failure reason
            for candidate_version in candidates:
                candidate_str = str(candidate_version)

                # Check 1: Constraints failure
                constraint_fail = False
                for requirer, req_range, _ in constraints:
                    if not req_range.contains(candidate_version):
                        constraint_fail = True
                        break

                if constraint_fail:
                    error_lines.append(f"  {package_name} {candidate_str} is excluded by the constraints")
                    continue

                # Check 2: Internal dependency conflict
                candidate_reqs = index.requirements(package_name, candidate_str)
                conflict_found = False
                for dep_name, dep_range in candidate_reqs.items():
                    if dep_name in current_selection:
                        selected_dep_version = current_selection[dep_name]
                        if not dep_range.contains(selected_dep_version):
                            error_lines.append(f"  {package_name} {candidate_str} requires {dep_name} {str(dep_range)}, but {dep_name} {str(selected_dep_version)} is selected")
                            conflict_found = True
                            break

                if conflict_found:
                    continue # Move to next candidate if conflict found

                # If we reach here, the version is acceptable w.r.t. selected deps, but since it didn't lead to success, 
                # and we are at the end of candidates loop, we rely on the earlier constraint/dependency failure.
                # The requirement states: "else NAME VERSION requires DEP RANGE, but DEP SELECTED is selected for its first conflicting dependency in alphabetical order of dependency names."
                # The logic above handles this by printing the first one found.
                pass # If it's acceptable w.r.t. selected deps, but still failed recursion, it's not the *first* step failure.

        else:
            error_lines.append(f"  no versions of {package_name} are known")

        explanation = "\n".join(error_lines)
        raise ResolutionError(package_name, explanation)


    # Start the DFS
    try:
        final_selection = dfs(order, selected_packages)
        if final_selection is not None:
            return final_selection
    except ResolutionError as e:
        # Re-raise the error as specified
        raise e

    # Fallback, though DFS should cover this
    raise ResolutionError("System", "Internal solver error: Search terminated without success or error.")
