import re

class Version:
    def __init__(self, text: str):
        parts = text.split('.')
        if len(parts) != 3:
            raise ValueError(f"Version '{text}' must have three parts.")
        try:
            self.major = int(parts[0])
            self.minor = int(parts[1])
            self.patch = int(parts[2])
        except ValueError:
            raise ValueError(f"Version parts must be integers: {text}")

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.major == other.major and self.minor == other.minor and self.patch == other.patch

    def __lt__(self, other):
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __gt__(self, other):
        return (self.major, self.minor, self.patch) > (other.major, other.minor, other.patch)

    def __le__(self, other):
        return (self.major, self.minor, self.patch) <= (other.major, other.minor, other.patch)

    def __ge__(self, other):
        return (self.major, self.minor, self.patch) >= (other.major, other.minor, other.patch)

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

class Range:
    def __init__(self, spec: str):
        self.spec = spec.strip()
        if not self.spec:
            raise ValueError("Range specification cannot be empty.")

        self.constraints = []
        parts = [p.strip() for p in self.spec.split(',')]

        for part in parts:
            if not part:
                raise ValueError("Empty constraint found in range specification.")

            part = part.strip()

            if part == "*":
                self.constraints.append(("*", None, None))
                continue

            # Check for caret (^) and tilde (~)
            if part.startswith('^'):
                op = '^'
                version_str = part[1:].strip()
                if not version_str:
                    raise ValueError("Caret range must be followed by a version.")

                try:
                    base_version = Version(version_str)
                    if base_version.major == 0 and base_version.minor == 0 and base_version.patch == 0:
                        upper_bound = Version(f"0.0.{base_version.patch + 1}")
                    elif base_version.major == 0:
                        upper_bound = Version(f"0.{base_version.minor + 1}.0")
                    else:
                        upper_bound = Version(f"{base_version.major + 1}.0.0")

                    self.constraints.append((op, base_version, upper_bound))
                except ValueError as e:
                    raise ValueError(f"Bad version in caret range: {part}. Error: {e}")
                continue

            if part.startswith('~'):
                op = '~'
                version_str = part[1:].strip()
                if not version_str:
                    raise ValueError("Tilde range must be followed by a version.")

                try:
                    base_version = Version(version_str)
                    if base_version.patch == 0:
                        upper_bound = Version(f"{base_version.major}.{base_version.minor + 1}.0")
                    else:
                        upper_bound = Version(f"{base_version.major}.{base_version.minor + 1}.0")

                    self.constraints.append((op, base_version, upper_bound))
                except ValueError as e:
                    raise ValueError(f"Bad version in tilde range: {part}. Error: {e}")
                continue

            # Standard operators: ==, !=, >=, <=, >, <
            match = re.match(r"(!=|<=|>=|>|<|==)(\d+\.\d+\.\d+)", part)

            if match:
                operator = match.group(1)
                version_str = match.group(2)
                try:
                    version = Version(version_str)
                    if operator == '==':
                        self.constraints.append(("==", version, None))
                    elif operator == '!=':
                        self.constraints.append(("!=", version, None))
                    elif operator == '>=':
                        self.constraints.append((">=", version, None))
                    elif operator == '<=':
                        self.constraints.append(("<=", version, None))
                    elif operator == '>':
                        self.constraints.append((">", version, None))
                    elif operator == '<':
                        self.constraints.append(("<", version, None))
                except ValueError as e:
                    raise ValueError(f"Bad version in constraint {part}. Error: {e}")
            else:
                raise ValueError(f"Unknown operator or format in constraint: {part}")

    def contains(self, v: Version) -> bool:
        for constraint in self.constraints:
            op = constraint[0]
            version = constraint[1]
            upper_bound = constraint[2]

            if op == "*":
                continue
            elif op == "==":
                if v != version:
                    return False
            elif op == "!=":
                if v == version:
                    return False
            elif op == ">=":
                if v < version:
                    return False
            elif op == "<=":
                if v > version:
                    return False
            elif op == ">":
                if v <= version:
                    return False
            elif op == "<":
                if v >= version:
                    return False
            elif op == "^":
                if v < version:
                    return False
                if version.major == 0 and version.minor == 0 and v >= upper_bound:
                    return False
                if version.major == 0 and version.minor > 0 and v >= upper_bound:
                    return False
            elif op == "~":
                if v < version:
                    return False
                if v >= upper_bound:
                    return False

        return True

    def __contains__(self, v: Version):
        return self.contains(v)

    def __str__(self):
        return self.spec
