from typing import Dict, List, Any
from resolve.versions import Version
from resolve.versions import RangeSpec

class PackageIndex:
    def __init__(self):
        # Structure: {name: {version_str: {'requires': {dep_name: spec_str}, 'version': Version}}}
        self._index: Dict[str, Dict[str, Dict[str, Any]]] = {}

    def add(self, name: str, version_str: str, requires: Dict[str, str] = None):
        if requires is None:
            requires = {}

        try:
            version = Version(version_str)
        except ValueError:
            raise ValueError(f"Invalid version '{version_str}'")

        if name not in self._index:
            self._index[name] = {}

        if version_str in self._index[name]:
            raise ValueError(f"Package {name} version {version_str} already exists in index.")

        # Validate all requirements specs
        for dep_name, spec_str in requires.items():
            try:
                RangeSpec(spec_str) # Test parsing
            except ValueError as e:
                raise ValueError(f"Invalid requirement spec for {name}: {e}")

        self._index[name][version_str] = {
            'requires': requires,
            'version': version
        }

    def versions(self, name: str) -> List[Version]:
        if name not in self._index:
            return []

        version_list = []
        for version_str in self._index[name]:
            version_list.append(self._index[name][version_str]['version'])

        # Sort newest first
        return sorted(version_list, reverse=True)

    def requirements(self, name: str, version_str: str) -> Dict[str, RangeSpec]:
        if name not in self._index or version_str not in self._index[name]:
            raise KeyError(f"Version {version_str} of package {name} not found.")

        requires = self._index[name][version_str]['requires']
        return {dep: RangeSpec(spec) for dep, spec in requires.items()}

    @classmethod
    def from_dict(cls, data: Dict[str, Any]):
        index = cls()
        for name, versions_data in data.items():
            for version_str, details in versions_data.items():
                requires = details.get('requires', {})
                index.add(name, version_str, requires)
        return index
