from typing import Dict, List, Tuple, Optional, Any
from resolve.versions import Version, RangeSpec
from resolve.index import PackageIndex

class ResolutionError(Exception):
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation
        super().__init__(explanation)

def resolve(index: PackageIndex, requirements: Dict[str, str]) -> Dict[str, Version]:

    initial_order = sorted(requirements.keys())

    # State tracking
    # order: List of package names in the order they should be processed
    # selected: Dict[name, Version] of packages already chosen
    order = list(initial_order)
    selected: Dict[str, Version] = {}

    # DFS stack simulation: (current_order, current_selected)
    # We only need to pass the state forward, and backtrack implicitly via recursion.

    def find_next_package(current_order: List[str], current_selected: Dict[str, Version]) -> Optional[str]:
        for pkg_name in current_order:
            if pkg_name not in current_selected:
                return pkg_name
        return None

    def backtrack(current_order: List[str], current_selected: Dict[str, Version]) -> Optional[Dict[str, Version]]:

        pkg_name = find_next_package(current_order, current_selected)

        if pkg_name is None:
            return current_selected # Success

        # 1. Determine constraints for pkg_name
        constraints: List[Tuple[str, RangeSpec]] = []

        # Root requirement constraint
        if pkg_name in requirements:
            try:
                root_spec = RangeSpec(requirements[pkg_name])
                constraints.append(('<root>', root_spec))
            except ValueError:
                # This should be caught earlier, but as a safeguard
                raise ResolutionError(pkg_name, f"Cannot resolve {pkg_name}\n  <root> requires {pkg_name} {requirements[pkg_name]}")

        # Constraints from already selected packages
        for selected_name, selected_version in current_selected.items():
            try:
                pkg_index = index # index is accessible in the closure scope
                requires_map = pkg_index.requirements(selected_name, str(selected_version))

                if pkg_name in requires_map:
                    spec = requires_map[pkg_name]
                    # Requirer format: "name version"
                    requirer_str = f"{selected_name} {str(selected_version)}"
                    constraints.append((requirer_str, spec))
            except KeyError:
                # Should not happen if selected_name/selected_version came from index
                pass

        # 2. Get candidates (newest first)
        candidates = index.versions(pkg_name)

        acceptable_candidates: List[Tuple[Version, List[str]]] = [] # (Version, new_deps_to_add)

        for candidate_version in candidates:
            is_acceptable = True
            conflicting_dependency_info = None # (dep_name, RangeSpec, selected_version_of_dep)

            # Check all constraints
            for constraint_str, spec in constraints:
                if not spec.contains(candidate_version):
                    is_acceptable = False
                    break

            if not is_acceptable:
                # Check for exclusion explanation
                explanation_lines = []
                if not candidates:
                     # This case is covered below, but for completeness in exclusion check:
                     pass
                else:
                     # Find the first reason for exclusion among constraints
                    for constraint_str, spec in constraints:
                        if not spec.contains(candidate_version):
                            if constraint_str.startswith('<root>'):
                                explanation_lines.append(f"  <root> requires {pkg_name} {spec.spec}")
                            else:
                                # e.g., app 1.0.0 requires lib <2.0.0
                                parts = constraint_str.split(' ', 1)
                                requirer = parts[0]
                                dep_name = parts[1].split(' ')[0]
                                dep_version_str = parts[1].split(' ')[1]
                                explanation_lines.append(f"  {requirer} requires {pkg_name} {spec.spec}")

                            # We only need ONE reason for the exclusion in the error message
                            # The requirement is to list constraints, so we check all later for the final error structure
                            pass

                    # If we reach here, we know it's excluded by at least one constraint
                    # We defer the full error construction until we exhaust all candidates/fail at this step.
                    pass
                continue # Not acceptable

            # Check dependencies of candidate_version against already selected packages
            deps_to_add = []
            dependencies_of_candidate = index.requirements(pkg_name, str(candidate_version))

            for dep_name, dep_spec in dependencies_of_candidate.items():
                if dep_name not in current_selected:
                    # Add dependency name to be considered later if not selected
                    deps_to_add.append(dep_name)
                else:
                    # Dependency is already selected, check if selected version satisfies requirement
                    selected_version = current_selected[dep_name]
                    if not dep_spec.contains(selected_version):
                        # Conflict found! Record for error explanation later.
                        conflicting_dependency_info = (dep_name, dep_spec, selected_version)
                        break # Stop checking other dependencies for this candidate

            if conflicting_dependency_info:
                continue # Not acceptable due to dependency conflict

            # Acceptable candidate found!
            acceptable_candidates.append((candidate_version, sorted(deps_to_add)))

        # 3. Try each acceptable candidate
        for candidate_version, new_deps in acceptable_candidates:

            # Prepare next state
            next_selected = current_selected.copy()
            next_selected[pkg_name] = candidate_version

            next_order = current_order + new_deps

            # Recurse
            result = backtrack(next_order, next_selected)

            if result is not None:
                return result # Success down this path

        # 4. No candidate worked for pkg_name. Construct and raise error.

        explanation_lines = [f"cannot resolve {pkg_name}"]

        # Add constraints
        for constraint_str, spec in constraints:
            if constraint_str.startswith('<root>'):
                explanation_lines.append(f"  <root> requires {pkg_name} {spec.spec}")
            else:
                parts = constraint_str.split(' ', 1)
                requirer = parts[0]
                dep_name = parts[1].split(' ')[0]
                dep_version_str = parts[1].split(' ')[1]
                explanation_lines.append(f"  {requirer} requires {pkg_name} {spec.spec}")

        # Check for known versions / exclusions
        if not candidates:
            explanation_lines.append(f"  no versions of {pkg_name} are known")
        else:
            # Check candidates again to build the exclusion message
            for candidate_version in candidates:
                is_acceptable = True

                # Check constraints again (for exclusion line generation)
                for constraint_str, spec in constraints:
                    if not spec.contains(candidate_version):
                        is_acceptable = False
                        # Format: NAME VERSION is excluded by the constraints
                        if constraint_str.startswith('<root>'):
                            explanation_lines.append(f"  {pkg_name} {str(candidate_version)} is excluded by the constraints")
                        else:
                            # This case is complex as the requirement implies the exclusion should be listed per constraint
                            # Since the prompt implies only *one* line per version regarding exclusion, 
                            # we stick to the general exclusion message if multiple constraints fail it.
                            # The example only showed this general message when it fails constraints.
                            explanation_lines.append(f"  {pkg_name} {str(candidate_version)} is excluded by the constraints")
                        break

                if is_acceptable:
                    # Check dependencies conflict for acceptable versions
                    deps_of_candidate = index.requirements(pkg_name, str(candidate_version))
                    found_conflict = False

                    for dep_name, dep_spec in deps_of_candidate.items():
                        if dep_name in current_selected:
                            selected_version = current_selected[dep_name]
                            if not dep_spec.contains(selected_version):
                                # Format: NAME VERSION requires DEP RANGE, but DEP SELECTED is selected
                                explanation_lines.append(f"  {pkg_name} {str(candidate_version)} requires {dep_name} {dep_spec.spec}, but {dep_name} {str(selected_version)} is selected")
                                found_conflict = True
                                break # First conflicting dependency in alphabetical order of dependency names

                    if not found_conflict and is_acceptable:
                        # This candidate *should* have succeeded, but we reached this point, which implies a logic flaw or we missed a required check.
                        # Based on the prompt, if it's acceptable and no conflict is found, it should have led to success.
                        # For robustness, if we reach here, it means it *was* acceptable and didn't fail dependency checks, but still failed the DFS path.
                        # Re-reading the prompt: "A candidate is acceptable if every constraint contains it and, for every dependency of the candidate that is already selected, the selected version is in the dependency's range."
                        # If we are here, it means the recursive call failed, not that the candidate was unacceptable.
                        # The error must be generated by the *next* step failing.
                        pass

        # The required format is based on the FIRST step that found no acceptable candidate.
        # The explanation for failure at pkg_name must detail why *no* candidate worked.
        # Let's refine the explanation for the "no candidate" case based on the example.

        # Re-evaluating the final error structure:
        # 1. cannot resolve NAME
        # 2. Constraint lines (all constraints)
        # 3. If no versions: no versions known
        # 4. Else: version exclusion lines (one per version)

        final_explanation_lines = [f"cannot resolve {pkg_name}"]

        # 2. Constraints
        for constraint_str, spec in constraints:
            if constraint_str.startswith('<root>'):
                final_explanation_lines.append(f"  <root> requires {pkg_name} {spec.spec}")
            else:
                parts = constraint_str.split(' ', 1)
                requirer = parts[0]
                dep_name = parts[1].split(' ')[0]
                dep_version_str = parts[1].split(' ')[1]
                final_explanation_lines.append(f"  {requirer} requires {pkg_name} {spec.spec}")

        # 3 & 4. Versions status
        if not candidates:
            final_explanation_lines.append(f"  no versions of {pkg_name} are known")
        else:
            for candidate_version in candidates:
                is_acceptable_by_constraints = all(spec.contains(candidate_version) for _, spec in constraints)

                if not is_acceptable_by_constraints:
                    final_explanation_lines.append(f"  {pkg_name} {str(candidate_version)} is excluded by the constraints")
                    continue

                # Check dependency conflicts for acceptable candidates
                deps_of_candidate = index.requirements(pkg_name, str(candidate_version))
                conflict_found = False

                for dep_name, dep_spec in deps_of_candidate.items():
                    if dep_name in current_selected:
                        selected_version = current_selected[dep_name]
                        if not dep_spec.contains(selected_version):
                            final_explanation_lines.append(f"  {pkg_name} {str(candidate_version)} requires {dep_name} {dep_spec.spec}, but {dep_name} {str(selected_version)} is selected")
                            conflict_found = True
                            break # First conflicting dependency alphabetically

                if not conflict_found:
                    # This means the candidate was acceptable but the recursion failed.
                    # The prompt implies the failure explanation should describe *why* a candidate was unacceptable.
                    # If a candidate is acceptable, it *should* lead to a successful path, otherwise, the error is not correctly attributed here.
                    # Following the example strictly: If a version is excluded by constraints OR by dependency conflict, it gets a line.
                    # Since we exhausted all candidates, and none led to success, we list all versions that failed one of these criteria.
                    # For versions that passed constraints and dependencies, we don't list them as they were "tried" but the path failed deeper.
                    pass 

        explanation = "\n".join(final_explanation_lines)
        raise ResolutionError(pkg_name, explanation)

    try:
        return backtrack(order, selected)
    except ResolutionError:
        # Re-raise the specific error captured by the solver
        raise
    except Exception as e:
        # Catch any other unexpected errors during the process
        raise ResolutionError("internal_error", f"An unexpected error occurred during resolution: {type(e).__name__}: {e}")
