from typing import List, Dict, Union
from resolve.versions import Version

class Range:
    def __init__(self, spec: str):
        self.constraints: List[Tuple[str, Version]] = []
        self._parse_spec(spec.strip())

    def _parse_spec(self, spec: str):
        if not spec:
            raise ValueError("Empty spec")

        parts = spec.split(',')

        for part in parts:
            part = part.strip()
            if not part:
                continue

            # Check for caret (^) and tilde (~) prefixes
            if part.startswith('^'):
                self._parse_caret(part[1:])
            elif part.startswith('~'):
                self._parse_tilde(part[1:])
            else:
                # Check for operators: ==, !=, >=, <=, >, <, or exact version
                self._parse_standard_constraint(part)

    def _parse_caret(self, version_spec: str):
        try:
            base_version = Version(version_spec)

            if base_version.major == 0 and base_version.minor == 0 and base_version.patch == 0:
                # ^0.0.0 is >=0.0.0, <0.0.1
                self.constraints.append(('<', Version(f"0.0.{base_version.patch + 1}")))
                self.constraints.append(('>=', Version(version_spec)))
            elif base_version.major == 0:
                # ^0.2.3 is >=0.2.3, <0.3.0
                new_minor = base_version.minor + 1
                new_version = Version(f"0.{new_minor}.0")
                self.constraints.append(('>=', base_version))
                self.constraints.append(('<', new_version))
            else:
                # ^1.2.3 is >=1.2.3, <2.0.0
                new_major = base_version.major + 1
                new_version = Version(f"{new_major}.0.0")
                self.constraints.append(('>=', base_version))
                self.constraints.append(('<', new_version))

        except ValueError as e:
            raise ValueError(f"Invalid caret specification {version_spec}: {e}")

    def _parse_tilde(self, version_spec: str):
        try:
            base_version = Version(version_spec)

            if base_version.major == 0 and base_version.minor == 0:
                # ~0.0.3 is >=0.0.3, <0.0.4
                new_patch = base_version.patch + 1
                new_version = Version(f"0.0.{new_patch}")
                self.constraints.append(('>=', base_version))
                self.constraints.append(('<', new_version))
            else:
                # ~1.2.3 is >=1.2.3, <1.3.0
                new_minor = base_version.minor + 1
                new_version = Version(f"{base_version.major}.{new_minor}.0")
                self.constraints.append(('>=', base_version))
                self.constraints.append(('<', new_version))
        except ValueError as e:
            raise ValueError(f"Invalid tilde specification {version_spec}: {e}")


    def _parse_standard_constraint(self, part: str):
        # Match operator (==, !=, >=, <=, >, <) or no operator (exact version)

        op = None
        version_str = part

        if part.startswith('=='):
            op = '=='
            version_str = part[2:]
        elif part.startswith('!='):
            op = '!='
            version_str = part[2:]
        elif part.startswith('>='):
            op = '>='
            version_str = part[2:]
        elif part.startswith('<='):
            op = '<='
            version_str = part[2:]
        elif part.startswith('>'):
            op = '>'
            version_str = part[1:]
        elif part.startswith('<'):
            op = '<'
            version_str = part[1:]
        else:
            # Assume exact match if no operator is found
            op = '=='

        try:
            version = Version(version_str)
            self.constraints.append((op, version))
        except ValueError:
            raise ValueError(f"Bad version in constraint: {part}")

    def contains(self, v: Version) -> bool:
        for op, constraint_v in self.constraints:
            if op == '==':
                if v != constraint_v:
                    return False
            elif op == '!=':
                if v == constraint_v:
                    return False
            elif op == '>':
                if not v > constraint_v:
                    return False
            elif op == '>=':
                if not v >= constraint_v:
                    return False
            elif op == '<':
                if not v < constraint_v:
                    return False
            elif op == '<=':
                if not v <= constraint_v:
                    return False
        return True

    def __in__(self, v: Version) -> bool:
        return self.contains(v)

    def __str__(self):
        # Reconstruct the spec string, removing whitespace
        parts = []
        for op, constraint_v in self.constraints:
            if op == '==':
                parts.append(f"=={str(constraint_v)}")
            elif op == '!=':
                parts.append(f"!={str(constraint_v)}")
            elif op == '>':
                parts.append(f">{str(constraint_v)}")
            elif op == '>=':
                parts.append(f">={str(constraint_v)}")
            elif op == '<':
                parts.append(f"<{str(constraint_v)}")
            elif op == '<=':
                parts.append(f"<={str(constraint_v)}")
            elif op == '^': # Should not happen if parsing is correct, but for safety
                 parts.append(f"^{str(constraint_v)}")
            elif op == '~':
                 parts.append(f"~{str(constraint_v)}")

        return ",".join(parts)


class RangeSpec:
    """Wrapper to hold the range string and parsed constraints for cleaner API."""
    def __init__(self, spec: str):
        self.spec = spec.strip()
        self.range = Range(spec)

    def contains(self, v: Version) -> bool:
        return self.range.contains(v)

    def __str__(self):
        return self.range.__str__()

# Expose RangeSpec for external use, Range is internal detail
RangeSpec = RangeSpec
