import sys
import argparse
import json
from typing import Iterator
from datetime import datetime
from logagg.parsers import read_records, ParseError
from logagg.stats import filter_records, summarize

def time_from_arg(time_str: str) -> datetime:
    """Parses time string into timezone-aware datetime object (defaults to UTC)."""
    try:
        # Try ISO format first (handles offsets)
        return datetime.fromisoformat(time_str)
    except ValueError:
        # Assume UTC if no offset is present
        try:
            return datetime.strptime(time_str, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            raise argparse.ArgumentTypeError(f"Invalid time format: {time_str}")


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description="Log Aggregator")
    parser.add_argument('files', nargs='+', help='Input log files.')
    parser.add_argument('--format', choices=['auto', 'clf', 'jsonl'], default='auto', help='Log line format.')
    parser.add_argument('--since', type=time_from_arg, help='Filter records since this time (ISO 8601).')
    parser.add_argument('--until', type=time_from_arg, help='Filter records until this time (ISO 8601).')
    parser.add_argument('--status', type=str, help='Filter by status code (e.g., "4xx" or "404").')
    parser.add_argument('--top', type=int, default=3, help='Number of top paths to report.')
    parser.add_argument('--json', action='store_true', help='Output summary as JSON.')

    args = parser.parse_args(argv)

    all_records: list = []
    all_bad_lines: list = []

    # 1. Read all records and count bad lines
    for file_path in args.files:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                lines = f.readlines()
            records, bad_lines = read_records(iter(lines), args.format)
            all_records.extend(records)
            all_bad_lines.extend(bad_lines)
        except FileNotFoundError:
            print(f"error: File not found: {file_path}", file=sys.stderr)
            return 2
        except Exception as e:
            print(f"error: Could not read file {file_path}: {e}", file=sys.stderr)
            return 2

    # 2. Filter records
    try:
        filtered_records = filter_records(all_records, args.since, args.until, args.status)
    except ValueError as e:
        print(f"error: {e}", file=sys.stderr)
        return 2

    # 3. Summarize
    try:
        summary = summarize(filtered_records, args.top)
    except ValueError as e:
        print(f"error: {e}", file=sys.stderr)
        return 2

    # 4. Output
    if args.json:
        summary['bad_lines'] = len(all_bad_lines)
        print(json.dumps(summary, indent=2))
    else:
        # Custom text output format
        print(f"requests: {summary['requests']}")
        print(f"bad lines: {len(all_bad_lines)}")
        print(f"bytes: {summary['bytes']}")

        status_line = " ".join([f"{k}={v}" for k, v in summary['classes'].items()])
        print(f"status: {status_line}")

        latency_data = summary['latency_ms']
        if latency_data['count'] > 0:
            latency_str = (
                f"p50={latency_data['p50']:.1f} ms p95={latency_data['p95']:.1f} ms max={latency_data['max']:.1f} ms"
            )
        else:
            latency_str = "n/a"
        print(f"latency: {latency_str}")

        print("top paths:")
        if summary['top_paths']:
            for path, count in summary['top_paths']:
                print(f"  {count} {path}")
        else:
            print("  none")

    return 0

if __name__ == '__main__':
    sys.exit(main())
