    status: int
    size: int
    latency_ms: Optional[float]

class ParseError(ValueError):
    pass

def normalize(time: datetime, client: str, method: str, path: str, status: int, size: Optional[str], latency_ms: Optional[float]) -> Record:
    """Normalizes raw parsed fields into a Record instance."""

    # Time validation and conversion to UTC
    if time.tzinfo is None or time.tzinfo.utcoffset(time) is None:
        raise ParseError("Time must be timezone-aware.")
    time_utc = time.astimezone(timezone.utc)

    # Client validation
    if not isinstance(client, str) or not client:
        raise ParseError("Client must be a non-empty string.")

    # Method validation
    if not isinstance(method, str) or not method.isupper() or not method.isalpha():
        raise ParseError("Method must be a non-empty string of ASCII letters.")

    # Path validation and normalization
    if not isinstance(path, str) or not path.startswith('/'):
        raise ParseError("Path must start with '/'.")

    # Remove query/fragment and collapse slashes
    path_no_query = path.split('?')[0].split('#')[0]
    path_normalized = re.sub(r'/+', '/', path_no_query)
    if not path_normalized:
        raise ParseError("Path cannot be empty after normalization.")

    # Status validation
    if not isinstance(status, int) or not (100 <= status <= 599):
        raise ParseError(f"Status code {status} is out of range (100-599).")

    # Size validation
    size_int = 0
    if size is not None:
        size_str = str(size).strip('"')
        if size_str == '-' or size_str == '':
            size_int = 0
        else:
            try:
                size_int = int(size_str)
                if size_int < 0:
                    raise ParseError("Size cannot be negative.")
            except ValueError:
                raise ParseError(f"Size '{size}' is not a valid integer.")

    # Latency validation
    latency_float: Optional[float] = None
    if latency_ms is not None:
        if isinstance(latency_ms, (int, float)) and latency_ms >= 0:
            latency_float = float(latency_ms)
        else:
            raise ParseError("Latency must be a non-negative number or None.")

    return Record(
        time=time_utc,
        client=client,
        method=method,
        path=path_normalized,
        status=status,
        size=size_int,
        latency_ms=latency_float
    )

# --- CLF Parser ---

# Regex for Apache Common Log Format:
# client (ip) - ident user [time] "METHOD PATH PROTOCOL" status size [latency]
CLF_REGEX = re.compile(
    r'(\S+) \S+ \S+ \[(.+?)\] "(\S+) (.+?) \S+" (\d+) (\S+)(?: (\d+))?'
)

def parse_clf(line: str) -> Tuple[Any, ParseError]:
    """Parses a line in Apache Common Log Format."""
    match = CLF_REGEX.match(line)
    if not match:
        raise ParseError("Line does not match CLF format.")

    # Groups: 1:client, 2:time_str, 3:method, 4:path, 5:status, 6:size_str, 7:latency_str
    client = match.group(1)
    time_str = match.group(2)
    method = match.group(3)
    path = match.group(4)
    status = int(match.group(5))
    size_str = match.group(6)
    latency_str = match.group(7)

    # Time parsing: DD/Mon/YYYY:HH:MM:SS ±HHMM
    try:
        # Example: 10/Oct/2000:13:55:36 -0700
        dt_obj = datetime.strptime(time_str, '%d/%b/%Y:%H:%M:%S %z')
    except ValueError:
        raise ParseError(f"Could not parse time string: {time_str}")

    # Size parsing
    size = 0
    if size_str and size_str.isdigit():
        size = int(size_str)
    elif size_str == '-':
        size = 0
    else:
        # Should be caught by regex or be empty/malformed, but defensive coding
        pass 

    # Latency parsing (microseconds / 1000)
    latency_ms: Optional[float] = None
    if latency_str and latency_str.isdigit():
        # The spec says latency is in microseconds, so divide by 1000
        latency_ms = float(latency_str) / 1000.0

    return normalize(dt_obj, client, method, path, status, size_str, latency_ms)


# --- JSONL Parser ---

def parse_jsonl(line: str) -> Tuple[Any, ParseError]:
    """Parses a line in JSON Lines format."""
    try:
        data = json.loads(line)
    except json.JSONDecodeError:
        raise ParseError("Invalid JSON format.")

    # Required keys check
    required_keys = ['ts', 'client', 'method', 'path', 'status']
    for key in required_keys:
        if key not in data:
            raise ParseError(f"Missing required key: '{key}' in JSON record.")

    ts_str = data['ts']

    # Time parsing: ISO 8601 with offset or 'Z'
    try:
        if ts_str.endswith('Z'):
            # Handle 'Z' (Zulu/UTC)
            dt_obj = datetime.fromisoformat(ts_str[:-1] + '+00:00')
        else:
            # Standard ISO 8601 parsing, which handles offsets correctly
            dt_obj = datetime.fromisoformat(ts_str)
    except ValueError:
        raise ParseError(f"Time string '{ts_str}' is not a valid ISO 8601 format.")

    # Size parsing
    size = data.get('bytes')
    if size is None:
        size_val = None
    else:
        try:
            size_val = int(size)
        except (ValueError, TypeError):
            raise ParseError(f"'bytes' value '{size}' is not a valid integer.")

    # Latency parsing
    latency_ms = data.get('latency_ms')
    if latency_ms is not None:
        try:
            if isinstance(latency_ms, (int, float)) and latency_ms >= 0:
                latency_ms = float(latency_ms)
            else:
                raise ParseError(f"'latency_ms' value '{latency_ms}' is invalid.")
        except TypeError:
             raise ParseError(f"'latency_ms' value '{latency_ms}' is not a number.")

    # Normalization call
    return normalize(
        time=dt_obj, 
        client=str(data['client']), 
        method=str(data['method']), 
        path=str(data['path']), 
        status=int(data['status']), 
        size=size_val if size_val is not None else '-', # Use '-' to signify missing/0 for size_str in normalize
        latency_ms=latency_ms
    )

# --- Line Parser ---

def parse_line(line: str, fmt: str = 'auto') -> Tuple[Any, ParseError]:
    """Determines format and parses the line."""
    stripped_line = line.strip()

    if not stripped_line:
        # Should be handled by read_records, but for safety
        raise ParseError("Input line is empty or whitespace.")

    if fmt == 'jsonl':
        return parse_jsonl(line)
    elif fmt == 'clf':
        return parse_clf(line)
    elif fmt == 'auto':
        if stripped_line.startswith('{'):
            return parse_jsonl(line)
        else:
            return parse_clf(line)
    else:
        raise ValueError(f"Unsupported format specified: {fmt}")


# --- Record Reader ---

def read_records(lines: Iterator[str], fmt: str = 'auto') -> Tuple[List[Record], List[int]]:
    """Reads an iterable of lines, returning records and a list of 1-based line numbers that failed parsing."""
    records: List[Record] = []
    bad_lines: List[int] = []

    for i, line in enumerate(lines, 1):
        try:
            record = parse_line(line, fmt)
            records.append(record)
        except (ParseError, ValueError) as e:
            bad_lines.append(i)
            # Optionally log the error here if needed, but per spec, we just count it.
            # print(f"Bad line {i}: {e}") 
            pass

    return records, bad_lines
