from typing import List, Dict, Any, Optional
from datetime import datetime
from math import ceil

class ParseError(ValueError):
    pass

def percentile(values: List[float], p: int) -> float:
    """Calculates the p-th percentile using the nearest-rank method."""
    if not values:
        raise ValueError("Values list cannot be empty.")
    if not (0 < p <= 100):
        raise ValueError("Percentile p must be in the range (0, 100].")

    sorted_values = sorted(values)
    n = len(sorted_values)

    # Nearest-rank method: 1-based rank ceil(p / 100 * n)
    rank = int(ceil((p / 100) * n))

    # Rank is 1-based, list is 0-based
    return sorted_values[rank - 1]

def filter_records(records: List['Record'], since: Optional[datetime] = None, until: Optional[datetime] = None, status: Optional[str] = None) -> List['Record']:
    """Filters records based on time range and HTTP status code."""

    filtered = records

    # Time filtering
    if since is not None or until is not None:
        filtered = [
            r for r in filtered 
            if (since is None or r.time >= since) and (until is None or r.time < until)
        ]

    # Status filtering
    if status is not None:
        status_filter_code = None
        is_class_filter = False

        if status.startswith(('1xx', '2xx', '3xx', '4xx', '5xx')):
            is_class_filter = True
            status_code_prefix = status[:3]
        elif status.isdigit():
            status_code_prefix = status
        else:
            raise ValueError("Status must be a status code string ('1xx'...'5xx') or an exact digit string.")

        if is_class_filter:
            try:
                class_num = int(status_code_prefix[0])
                filtered = [
                    r for r in filtered 
                    if 100 <= r.status < 600 and int(status_code_prefix[0]) * 100 <= r.status < (int(status_code_prefix[0]) + 1) * 100
                ]
            except:
                 raise ValueError("Invalid status class provided.")
        elif status_code_prefix.isdigit():
            try:
                target_status = int(status_code_prefix)
                filtered = [r for r in filtered if r.status == target_status]
            except ValueError:
                raise ValueError("Invalid exact status code provided.")

    return filtered

def summarize(records: List['Record'], top: int = 3) -> Dict[str, Any]:
    """Generates summary statistics from a list of records."""

    if not isinstance(top, int) or top < 0:
        raise ValueError("Top value must be a non-negative integer.")

    requests = len(records)

    # Initialize aggregators
    total_bytes = 0
    status_classes: Dict[str, int] = {'1xx': 0, '2xx': 0, '3xx': 0, '4xx': 0, '5xx': 0}
    status_counts: Dict[str, int] = {}
    latencies: List[float] = []
    path_counts: Dict[str, int] = {}
    first_time: Optional[datetime] = None
    last_time: Optional[datetime] = None

    for record in records:
        # Bytes sum
        total_bytes += record.size

        # Status class count
        status_code = record.status
        if 100 <= status_code < 200:
            status_classes['1xx'] += 1
        elif 200 <= status_code < 300:
            status_classes['2xx'] += 1
        elif 300 <= status_code < 400:
            status_classes['3xx'] += 1
        elif 400 <= status_code < 500:
            status_classes['4xx'] += 1
        elif 500 <= status_code < 600:
            status_classes['5xx'] += 1

        # Status code count
        status_str = str(status_code)
        status_counts[status_str] = status_counts.get(status_str, 0) + 1

        # Latency
        if record.latency_ms is not None:
            latencies.append(record.latency_ms)

        # Top paths
        path_counts[record.path] = path_counts.get(record.path, 0) + 1

        # Time tracking
        if first_time is None or record.time < first_time:
            first_time = record.time
        if last_time is None or record.time > last_time:
            last_time = record.time

    # Calculate Latency stats
    latency_summary = {}
    if latencies:
        latency_summary['count'] = len(latencies)
        latency_summary['p50'] = percentile(latencies, 50)
        latency_summary['p95'] = percentile(latencies, 95)
        latency_summary['max'] = max(latencies)
    else:
        latency_summary['count'] = 0
        latency_summary['p50'] = None
        latency_summary['p95'] = None
        latency_summary['max'] = None

    # Calculate Top paths
    sorted_paths = sorted(path_counts.items(), key=lambda item: (-item[1], item[0]))
    top_paths_list = [[path, count] for path, count in sorted_paths[:top]]

    # Construct final summary
    summary: Dict[str, Any] = {
        "requests": requests,
        "bytes": total_bytes,
        "classes": status_classes,
        "codes": dict(sorted(status_counts.items())),
        "latency_ms": latency_summary,
        "top_paths": top_paths_list,
        "first": first_time.isoformat() if first_time else None,
        "last": last_time.isoformat() if last_time else None,
    }

    return summary
