import sys
import argparse
import json
from datetime import datetime
from typing import List, Tuple

from logagg.parsers import parse_line, read_records
from logagg.stats import filter_records, summarize

def parse_time(time_str: str) -> datetime:
    try:
        dt = datetime.fromisoformat(time_str.replace('Z', '+00:00'))
        if dt.tzinfo is None:
            # Treat naive datetime as UTC per spec
            return dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except ValueError:
        raise argparse.ArgumentTypeError(f"Invalid ISO 8601 time format: {time_str}")

def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description="Log file aggregator and summarizer.")
    parser.add_argument('files', metavar='FILE', nargs='+', help='Input log files.')
    parser.add_argument('--format', choices=['auto', 'clf', 'jsonl'], default='auto', help='Log format to parse.')
    parser.add_argument('--since', type=parse_time, help='Start time for filtering (ISO 8601).')
    parser.add_argument('--until', type=parse_time, help='End time for filtering (ISO 8601).')
    parser.add_argument('--status', type=str, help='Filter by status code or class (e.g., "404" or "4xx").')
    parser.add_argument('--top', type=int, default=3, help='Number of top paths to show.')
    parser.add_argument('--json', action='store_true', help='Output summary as JSON.')

    args = parser.parse_args(argv)

    all_lines: List[str] = []
    for filepath in args.files:
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                all_lines.extend(f.readlines())
        except FileNotFoundError:
            print(f"error: File not found: {filepath}", file=sys.stderr)
            return 2
        except UnicodeDecodeError:
            print(f"error: Could not read file {filepath} as UTF-8", file=sys.stderr)
            return 2

    # 1. Read records and count bad lines (before filtering)
    records, bad_lines = read_records(all_lines, args.format)
    bad_line_count = len(bad_lines)

    # 2. Filter records
    filtered_records = filter_records(records, args.since, args.until, args.status)

    # 3. Summarize
    summary = summarize(filtered_records, args.top)

    # 4. Add bad lines count if requested
    if args.json:
        summary['bad_lines'] = bad_line_count
        print(json.dumps(summary, indent=2))
        return 0

    # 5. Custom Text Output
    print(f"requests: {summary['requests']}")
    print(f"bad lines: {bad_line_count}")
    print(f"bytes: {summary['bytes']}")

    # Status line
    status_str = " ".join([f"{cls}={count}" for cls, count in summary['classes'].items()])
    print(f"status: {status_str}")

    # Latency line
    latency_data = summary['latency_ms']
    if latency_data['count'] > 0:
        latency_line = (
            f"latency: p50={latency_data['p50']:.1f} ms p95={latency_data['p95']:.1f} ms max={latency_data['max']:.1f} ms"
        )
    else:
        latency_line = "latency: n/a"
    print(latency_line)

    # Top paths
    print("top paths:")
    if not summary['top_paths']:
        print("  none")
    else:
        for path, count in summary['top_paths']:
            print(f"  {count} {path}")

    return 0

if __name__ == "__main__":
    # When running as python -m logagg.cli, sys.argv[0] is 'logagg.cli' 
    # and we pass sys.argv[1:] to main.
    sys.exit(main(sys.argv[1:]))
