from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Optional, Any, Dict, List, Tuple

class ParseError(ValueError):
    pass

@dataclass(frozen=True)
class Record:
    time: datetime
    client: str
    method: str
    path: str
    status: int
    size: int
    latency_ms: Optional[float]

def normalize(time: datetime, client: str, method: str, path: str, status: int, size: int, latency_ms: Optional[float]) -> Record:
    if not isinstance(time, datetime) or time.tzinfo is None:
        raise ParseError("Time must be a timezone-aware datetime")
    time_utc = time.astimezone(timezone.utc)

    if not isinstance(client, str) or not client:
        raise ParseError("Client must be a non-empty string")

    if not isinstance(method, str) or not method.isalpha() or not method.isupper():
        raise ParseError("Method must be a non-empty string of ASCII letters")
    method_upper = method.upper()

    if not isinstance(path, str) or not path.startswith('/'):
        raise ParseError("Path must start with '/'")

    # Remove everything from the first '?' or '#'
    if '?' in path:
        path = path.split('?')[0]
    if '#' in path:
        path = path.split('#')[0]

    # Collapse runs of '/'
    while '//' in path:
        path = path.replace('//', '/')

    if not isinstance(status, int):
        try:
            status = int(str(status))
        except (ValueError, TypeError):
            raise ParseError("Status must be an integer or convertible string")

    if not (100 <= status <= 599):
        raise ParseError("Status must be between 100 and 599")

    if isinstance(size, str):
        try:
            size = int(size)
        except ValueError:
            raise ParseError("Size must be an integer or convertible string")

    if size < 0:
        raise ParseError("Size must be non-negative")

    if latency_ms is not None and (not isinstance(latency_ms, (int, float)) or latency_ms < 0):
        raise ParseError("Latency must be None or a non-negative number")

    return Record(time=time_utc, client=client, method=method_upper, path=path, status=status, size=size, latency_ms=float(latency_ms) if latency_ms is not None else None)

