from dateutil import parser

# Apache Common Log Format Regex:
# 127.0.0.1 - frank [10/Oct/2000:13:55:36 -0700] \"GET /apache_pb.gif?x=1 HTTP/1.0\" 200 2326
CLF_REGEX = re.compile(
    r'(\S+)\s+\S+\s+\S+\s+\[(.*?)\]\s+"(\S+)\s+(\S+)\s+\S+"\s+(\d+)\s+(\S+)(?:\s+(\d+))?'
)

def parse_clf(line: str) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    match = CLF_REGEX.match(line)
    if not match:
        raise ParseError("Line does not match CLF format")

    client, time_str, method, path, status_str, size_str, latency_str = match.groups()

    # Time parsing: DD/Mon/YYYY:HH:MM:SS ±HHMM
    try:
        # dateutil.parser is used for robust parsing of varied time strings
        dt_obj = parser.parse(time_str)
    except Exception:
        raise ParseError(f"Could not parse time string: {time_str}")

    # Size parsing: None or "-" means 0
    size = 0
    if size_str and size_str.isdigit():
        size = int(size_str)

    # Latency parsing: microseconds / 1000
    latency_ms = None
    if latency_str and latency_str.isdigit():
        latency_ms = int(latency_str) / 1000.0

    return {
        "time": dt_obj, "client": client, "method": method, "path": path, 
        "status": int(status_str), "size": size, "latency_ms": latency_ms
    }, {}

import json
from datetime import datetime
from typing import Tuple, Dict, Any

def parse_jsonl(line: str) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    try:
        data = json.loads(line)
    except json.JSONDecodeError:
        raise ParseError("Invalid JSON format")

    required_keys = ['ts', 'client', 'method', 'path', 'status']
    if not all(k in data for k in required_keys):
        raise ParseError("Missing required keys in JSON record")

    ts_str = data['ts']

    try:
        # ISO 8601 parsing. Must have offset or end in Z.
        dt_obj = parser.parse(ts_str)
    except Exception:
        raise ParseError(f"Could not parse timestamp: {ts_str}")

    # Ensure timezone awareness: If no offset, assume UTC (as per spec)
    if dt_obj.tzinfo is None or dt_obj.tzinfo.utcoffset(dt_obj) is None:
        dt_obj = dt_obj.replace(tzinfo=timezone.utc)

    # Size parsing: optional 'bytes' key
    size = 0
    if 'bytes' in data and data['bytes'] is not None:
        try:
            size = int(data['bytes'])
        except (ValueError, TypeError):
            raise ParseError("Bytes value is not a valid integer")

    latency_ms = data.get('latency_ms')
    if latency_ms is not None:
        if not isinstance(latency_ms, (int, float)) or latency_ms < 0:
            raise ParseError("Latency_ms must be None or a non-negative number")
        latency_ms = float(latency_ms)

    return {
        "time": dt_obj, "client": data['client'], "method": data['method'], 
        "path": data['path'], "status": int(data['status']), "size": size, 
        "latency_ms": latency_ms
    }, {}

def parse_line(line: str, fmt: str) -> Tuple[Any, Dict[str, Any]]:
    if fmt == 'clf':
        return parse_clf(line)
    elif fmt == 'jsonl':
        return parse_jsonl(line)
    elif fmt == 'auto':
        stripped_line = line.lstrip()
        if stripped_line.startswith('{'):
            return parse_jsonl(line)
        else:
            return parse_clf(line)
    else:
        raise ValueError(f"Unsupported format: {fmt}")

def read_records(lines: List[str], fmt: str) -> Tuple[List[Record], List[int]]:
    records: List[Record] = []
    bad_lines: List[int] = []

    for i, line in enumerate(lines):
        line_num = i + 1
        stripped_line = line.strip()
        if not stripped_line:
            continue

        try:
            data, _ = parse_line(line, fmt)
            # Normalization is handled inside the parser functions in this setup,
            # but we must ensure the data dict conforms to the expected structure for Record creation.
            # Since the parsers now return dicts that contain all necessary fields, we pass them to normalize.

            # Note: The spec says both parsers pass to normalize.
            # We must adapt here to use the structure returned by the parsers.

            record = normalize(
                time=data['time'],
                client=data['client'],
                method=data['method'],
                path=data['path'],
                status=data['status'],
                size=data['size'],
                latency_ms=data['latency_ms']
            )
            records.append(record)
        except ParseError as e:
            bad_lines.append(line_num)
        except Exception:
            # Catch unexpected errors during parsing as bad lines too
            bad_lines.append(line_num)

    return records, bad_lines
