from logagg.parsers import Record, ParseError
from typing import List, Dict, Any

def percentile(values: List[float], p: int) -> float:
    if not (0 < p <= 100):
        raise ValueError("p must be in (0, 100]")
    if not values:
        raise ValueError("values list cannot be empty")

    sorted_values = sorted(values)
    n = len(sorted_values)
    # Nearest-rank method: ceil(p / 100 * n)
    rank = int((p / 100.0) * n)
    if rank == 0:
        rank = 1

    return sorted_values[rank - 1]

def filter_records(records: List[Record], since: Optional[datetime], until: Optional[datetime], status: Optional[str]) -> List[Record]:
    filtered = records

    if since:
        filtered = [r for r in filtered if r.time >= since]
    if until:
        filtered = [r for r in filtered if r.time < until]

    if status:
        if status.isdigit():
            target_status = int(status)
            filtered = [r for r in filtered if r.status == target_status]
        elif status.startswith(('1', '2', '3', '4', '5')):
            try:
                class_prefix = status[0]
                start = int(class_prefix) * 100
                end = (int(class_prefix) + 1) * 100 - 1
                filtered = [r for r in filtered if start <= r.status <= end]
            except ValueError:
                raise ValueError("Invalid status format for class filtering.")
        else:
            raise ValueError("Status must be a digit string or a class prefix string (e.g., '4xx').")

    return filtered

def summarize(records: List[Record], top: int) -> Dict[str, Any]:
    if top < 0:
        raise ValueError("top must be non-negative")

    requests = len(records)
    bytes_sum = sum(r.size for r in records)

    # Status classes
    class_counts: Dict[str, int] = {f"{i}xx": 0 for i in range(1, 6)}
    status_counts: Dict[str, int] = {}

    for r in records:
        class_counts[f"{r.status // 100}xx"] += 1
        status_counts[str(r.status)] = status_counts.get(str(r.status), 0) + 1

    # Latency statistics
    latencies = [r.latency_ms for r in records if r.latency_ms is not None]
    latency_count = len(latencies)
    p50, p95, max_latency = None, None, None

    if latency_count > 0:
        p50 = percentile(latencies, 50)
        p95 = percentile(latencies, 95)
        max_latency = max(latencies)

    # Top Paths
    path_counts: Dict[str, int] = {}
    for r in records:
        path_counts[r.path] = path_counts.get(r.path, 0) + 1

    sorted_paths = sorted(path_counts.items(), key=lambda item: (-item[1], item[0]))
    top_paths = [[path, count] for path, count in sorted_paths[:top]]

    # First and Last time
    first_time = min([r.time for r in records], default=None)
    last_time = max([r.time for r in records], default=None)

    return {
        "requests": requests,
        "bytes": bytes_sum,
        "classes": class_counts,
        "codes": dict(sorted(status_counts.items())),
        "latency_ms": {
            "count": latency_count,
            "p50": p50,
            "p95": p95,
            "max": max_latency
        },
        "top_paths": top_paths,
        "first": first_time.isoformat() if first_time else None,
        "last": last_time.isoformat() if last_time else None
    }
